import '@servicenow/sdk/global'
import { Flow, wfa, action, trigger } from '@servicenow/sdk/automation'

// Test: Nested ForEach with multiple lookUpRecords - Pattern A (multiple tables)
Flow(
    {
        $id: Now.ID['foreach_metadata_nested_lookups_flow'],
        name: 'ForEach Metadata - Nested Lookups Test',
        description: 'Tests metadata extraction with nested forEach loops on different tables',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['incident_created_trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        const incidents = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_incidents'],
                annotation: 'Lookup high priority incidents',
            },
            {
                table: 'incident',
                conditions: 'priority=1^active=true',
            }
        )

        wfa.flowLogic.forEach(
            wfa.dataPill(incidents.Records, 'records'),
            { $id: Now.ID['foreach_incidents'], annotation: 'Process each incident' },
            (incident) => {
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['log_incident_number'], annotation: 'Log incident number' },
                    {
                        log_level: 'info',
                        log_message: `Processing incident: ${wfa.dataPill(incident.number, 'string')}`,
                    }
                )

                const assignees = wfa.action(
                    action.core.lookUpRecords,
                    {
                        $id: Now.ID['lookup_assignees'],
                        annotation: 'Lookup potential assignees',
                    },
                    {
                        table: 'sys_user',
                        conditions: 'active=true',
                    }
                )

                wfa.flowLogic.forEach(
                    wfa.dataPill(assignees.Records, 'records'),
                    { $id: Now.ID['foreach_assignees'], annotation: 'Process each assignee' },
                    (assignee) => {
                        wfa.action(
                            action.core.log,
                            { $id: Now.ID['log_assignee_info'], annotation: 'Log assignee information' },
                            {
                                log_level: 'info',
                                log_message: `Assignee: ${wfa.dataPill(assignee.name, 'string')}`,
                            }
                        )
                    }
                )
            }
        )
    }
)
